function slots(c){c=c||C();const p=c.plan,out=[];if(!p||!Array.isArray(p.levels))return out;let un=0;
  p.levels.forEach((lv,li)=>(lv.units||[]).forEach((u,ui)=>{un++;(u.lessons||[]).forEach((l,k)=>{if(!l||!isS(l.id)||!isS(l.t))return;
    const key=l.use?String(l.use):"L."+l.id,mi=M.findIndex(m=>String(m.id)===key&&m.course===c.id);out.push({l,u,lv,li,ui,un,k,key,mi,n:out.length})})}));return out}
function bindPlan(){Object.values(COURSES).forEach(c=>slots(c).forEach(x=>{if(x.mi>=0){const m=M[x.mi];m.st=x.l.t;if(isS(x.l.g))m.topic=x.l.g;m.slot=x.l.id}}))}
const mine=()=>{const ss=slots(),keys=new Set(ss.map(x=>x.key)),inPlan=ss.filter(x=>x.mi>=0).map(x=>x.mi);
  const extra=M.map((m,i)=>i).filter(i=>M[i].course===C().id&&!keys.has(String(M[i].id))&&(M[i].custom||!ss.length));
  return inPlan.concat(extra.sort((a,b)=>(M[a].order||0)-(M[b].order||0)))};
const isDone=x=>!!(S[x.key]&&S[x.key].done);
const current=()=>{const ss=slots(),lo=S.ob?Math.floor(S.ob.lv||0):0;return ss.find(x=>!isDone(x)&&x.li>=lo)||ss.find(x=>!isDone(x))||null};
function openSlot(x){if(x.mi>=0)return go(x.mi);if(AI)return creer({slot:x});
  speakNote("Cette leçon n'est pas encore prête. Elle se prépare avec l'assistant, qui a besoin du réseau : réessaie quand tu captes.")}
function stopRow(x,cls,label,stateText,pct,fn){const li=el("li"),s=el("button","stop "+cls);s.type="button";
  s.innerHTML='<span class="time"></span><span class="rail"><span class="dot"></span></span><span class="card"><h2></h2><span class="topic"></span><span class="state"></span>'+(pct?'<span class="meter"><i style="width:'+pct+'%"></i></span>':"")+"</span>";
  s.querySelector(".time").textContent=label;s.querySelector("h2").textContent=x.t;s.querySelector(".topic").textContent=x.g||"";s.querySelector(".state").textContent=stateText;
  s.onclick=fn;li.append(s);return li}
function slotState(x){const m=x.mi>=0?M[x.mi]:null,st=S[x.key]||{};
  if(st.done)return{cls:"done",txt:"Terminée · "+(st.best!=null?st.best+" % de réussite":"")};
  if(m&&st.i){const n=screens(m).length;return{cls:"",txt:"En cours · reprendre",pct:Math.round(100*st.i/n)}}
  if(m)return{cls:"",txt:"Prête · environ 25 min"};
  return{cls:"todo",txt:AI?"À préparer · 2 à 3 minutes":"À préparer avec l'assistant"}}

function logErr(l,q,a){S.err=(S.err||[]).concat([{t:day(),l,q:String(q).slice(0,260),a:String(a).slice(0,160)}]).slice(-40)}
/* Sauvegarde dans le compte : un document privé par personne (data/users/<id>/progress), le navigateur ne sert que de copie de secours. */
let cloud=null,syncState="load",dirty=false,writing=false,who="",view="home";
const SYNC={load:"Chargement de ta progression…",ok:"Progression enregistrée dans ton compte Claude",saving:"Enregistrement…",
  local:"Compte indisponible ici : la progression reste sur cet appareil uniquement.",err:"Enregistrement impossible pour l'instant : la progression reste sur cet appareil."};
const syncText=()=>SYNC[syncState]+(who&&syncState==="ok"?" · "+who:"");
function syncEl(){const e=el("div","sync");e.dataset.sync=syncState;e.textContent=syncText();e.setAttribute("role","status");return e}
function setSync(x){syncState=x;document.querySelectorAll(".sync").forEach(e=>{e.dataset.sync=x;e.textContent=syncText()})}
async function push(){if(!cloud)return;dirty=true;if(writing)return;writing=true;setSync("saving");let fail=false;
  while(dirty&&!fail){dirty=false;const body={json:JSON.stringify(S),t:S.t||0};
    try{await cloud.set(body)}catch(e){if(e&&e.code==="unavailable"){await new Promise(r=>setTimeout(r,700+Math.random()*900));try{await cloud.set(body)}catch(e2){fail=true}}else fail=true}}
  writing=false;setSync(fail?"err":"ok")}
const save=()=>{S.t=Date.now();local();push()};
function merge(a,b){const ra=a.r||0,rb=b.r||0;if(ra!==rb)return ra>rb?a:b;
  const nw=(a.t||0)>=(b.t||0)?a:b,ol=nw===a?b:a,o={t:Math.max(a.t||0,b.t||0)};if(ra)o.r=ra;
  for(const i of new Set(Object.keys(a).concat(Object.keys(b)).filter(k=>/^\d+$/.test(k)||k.startsWith("L.")))){const x=nw[i],y=ol[i];if(!x&&!y)continue;if(!x||!y){o[i]=x||y;continue}
    const base=(!x.done&&!y.done&&(y.i||0)>(x.i||0))?y:x,m=Object.assign({},base);
    if(x.done||y.done){m.done=true;m.best=Math.max(x.best||0,y.best||0)}o[i]=m}
  const dd=Object.assign({},ol.d);for(const k in nw.d||{})dd[k]=Math.max(dd[k]||0,nw.d[k]);if(Object.keys(dd).length)o.d=dd;
  ["v","nb","cw","sr","cv","nbt"].forEach(k=>{const x=Object.assign({},ol[k],nw[k]);if(Object.keys(x).length)o[k]=x});const qz=nw.qz||ol.qz;if(qz)o.qz=qz;["err","req","course"].forEach(k=>{const x=nw[k]!=null?nw[k]:ol[k];if(x!=null)o[k]=x});const kept=new Set(Object.keys(o));for(const src of [ol,nw])for(const k in src)if(!kept.has(k)&&!/^\d+$/.test(k)&&!k.startsWith("L.")&&src[k]!=null)o[k]=src[k];return o}
async function connect(){try{
    if(!window.claude||!window.claude.use)return setSync("local");
    window.claude.use("sample").then(x=>{AI=x||null;if(AI&&view==="home")home()}).catch(()=>{});
    const [user,db]=await Promise.all([window.claude.use("user"),window.claude.use("db")]);
    if(db){DB=db;loadBase(db)}
    const uid=user?await user.id():null;if(!db||!uid)return setSync("local");
    try{who=(await user.name())||""}catch(e){}
    const ref=db.doc("data/users/"+uid+"/progress"),snap=await ref.get();let remote=null;
    if(snap.exists){try{remote=JSON.parse(snap.data().json)}catch(e){}}
    cloud=ref;
    if(remote&&typeof remote==="object"){S=merge(S,remote);local();if(view==="home")home();
      if(JSON.stringify(S)!==JSON.stringify(remote))push();else setSync("ok")}
    else if(Object.keys(S).length)push();else setSync("ok")
  }catch(e){setSync(cloud?"err":"local")}}
const el=(t,c,h)=>{const e=document.createElement(t);if(c)e.className=c;if(h!=null)e.innerHTML=h;return e};
const btn=(txt,c)=>{const b=el("button","btn"+(c?" "+c:""));b.type="button";b.textContent=txt;return b};
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const norm=s=>s.toLowerCase().replace(/[’`]/g,"'").replace(/\s+/g," ").trim();
const bare=s=>norm(s).replace(/([aeiou])'(?=\s|$|[.,!?])/g,"$1").normalize("NFD").replace(/[̀-ͯ]/g,"");
const fmt=q=>q.replace(/___/g,'<span class="blank"></span>').replace(/\(([^)]*)\)/g,"<small>($1)</small>");
const canSpeak="speechSynthesis" in window && "SpeechSynthesisUtterance" in window;
/* Synthèse vocale. Points délicats : une voix « réseau » (Google, par ex.) ne parle pas hors connexion ; Safari ignore un speak() lancé
   juste après cancel() ; Chrome peut rester en pause. On préfère donc une voix locale, on n'annule que si quelque chose parle,
   on relance sans voix imposée en cas d'erreur, et on prévient l'utilisateur si rien ne sort. */
let VOICES=[],UTT=null,speakTimer=0;
function loadVoices(){try{VOICES=speechSynthesis.getVoices()||[]}catch(e){VOICES=[]}}
if(canSpeak){loadVoices();try{speechSynthesis.addEventListener("voiceschanged",loadVoices)}catch(e){try{speechSynthesis.onvoiceschanged=loadVoices}catch(e2){}}}
function pickVoice(lang){if(!VOICES.length)loadVoices();const L=lang.toLowerCase().replace("_","-"),p=L.slice(0,2);
  const m=VOICES.filter(v=>v&&v.lang&&v.lang.toLowerCase().replace("_","-").startsWith(p));if(!m.length)return null;
  const exact=x=>x.lang.toLowerCase().replace("_","-")===L,loc=m.filter(v=>v.localService!==false);
  return loc.find(exact)||loc[0]||(navigator.onLine?(m.find(exact)||m[0]):null)}
function stopSpeech(){try{if(speechSynthesis.speaking||speechSynthesis.pending)speechSynthesis.cancel()}catch(e){}clearTimeout(speakTimer)}
function speakNote(msg){const old=document.querySelector(".speaknote");if(old)old.remove();if(!msg)return;
  const n=el("div","speaknote");n.setAttribute("role","status");n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),6000)}
function speak(t,rate){if(!canSpeak)return speakNote("Ce navigateur ne sait pas lire le texte à voix haute.");
  const lang=C().speech||"it-IT",text=String(t).replace(/ \/ /g,", ");let started=false,retried=false;
  const go=withVoice=>{const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=rate||.9;
    const v=withVoice?pickVoice(lang):null;if(v)u.voice=v;
    u.onstart=()=>{started=true;speakNote("")};
    u.onerror=e=>{const err=e&&e.error;if(err==="interrupted"||err==="canceled")return;
      if(!retried){retried=true;go(false);return}
      speakNote(err==="network"||err==="synthesis-unavailable"?"La voix demande une connexion. Installe une voix en "+LN()+" utilisable hors ligne dans les réglages de synthèse vocale de ton appareil.":"La lecture a échoué. Vérifie le son, puis réessaie.")};
    UTT=u;try{speechSynthesis.resume()}catch(e){}speechSynthesis.speak(u)};
  try{stopSpeech();go(true)}catch(e){return speakNote("La lecture a échoué. Réessaie.")}
  speakTimer=setTimeout(()=>{if(started)return;let busy=false;try{busy=speechSynthesis.speaking}catch(e){}if(busy)return;
    speakNote(pickVoice(lang)?"Rien ne sort ? Monte le volume et vérifie que le téléphone n'est pas en mode silencieux.":"Aucune voix en "+LN()+" n'est installée sur cet appareil. Ajoute-la dans les réglages de synthèse vocale (accessibilité), puis recharge la page.")},2500)}
function sayBtn(t,label){const b=el("button","say",'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M16.5 8.5a5 5 0 0 1 0 7"/></svg><span></span>');
  b.type="button";b.querySelector("span").textContent=label||"Écouter";b.onclick=()=>speak(t);return b}
/* Si l'élève recopie toute la phrase au lieu du seul mot manquant, on en extrait ce qui remplit le(s) trou(s). */
function blankOf(q,u){const pun=/[.,;:!?¿¡«»"…]/g,cl=t=>String(t).toLowerCase().replace(/[’`]/g,"'").replace(pun," ").replace(/\s+/g," ").trim();
  const parts=cl(q.replace(/\s*\([^)]*\)/g,"")).split(/\s*_{3,}\s*/);if(parts.length<2)return u;
  const re=new RegExp("^"+parts.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("\\s*(.+?)\\s*")+"$"),m=cl(u).match(re);
  return m?m.slice(1).map(x=>x.trim()).join(" / "):u}
function filled(q,a){const parts=a.split(" / ");let k=0;return q.replace(/\s*\([^)]*\)/g,"").replace(/___/g,()=>parts[Math.min(k++,parts.length-1)])}
function screens(m){const a=[];m.lessons.forEach(l=>a.push({t:"l",d:l}));a.push({t:"v"});m.ex.forEach(x=>a.push({t:x[0],d:x}));a.push({t:"d"});m.dq.forEach(x=>a.push({t:"m",d:x}));return a}
