SC.forEach((sc,i)=>{M[i].scenario=sc});
function convList(){cur=null;qbar(null,null,"Conversation");body.append(el("div","kind","Jeu de rôle"));body.append(el("h2",null,"Conversation"));
  if(!AI){body.append(el("p","fr","La conversation passe par l'assistant Claude, indisponible pour l'instant. Vérifie le réseau, puis réessaie."));return}
  body.append(el("p","fr","Tu écris en "+LN()+", l'assistant joue l'autre personnage et te répond. À la fin, un bilan reprend tes erreurs et les mots à retenir. Il faut du réseau."));
  const g=el("div","opts");mine().filter(i=>M[i].scenario).forEach(k=>{const sc=M[k].scenario,b=el("button","opt scn"),t=el("b"),d=el("span"),st=el("span","state");b.type="button";t.textContent=sc.title;d.textContent=sc.goal;
    st.textContent=M[k].st+((S.cv||{})[M[k].id]?" · déjà fait":"");b.append(t,d,st);b.onclick=()=>conv(k);g.append(b)});body.append(g)}
function conv(k){cur=null;const sc=M[k].scenario,turns=[];let n=0;
  const RULES="Jeu de rôle pour un francophone qui apprend cette langue : "+LN()+" (niveau "+(C().level||"A2 vers B1")+"). Tu joues : "+sc.role+". Tu as ouvert la conversation avec : «"+sc.open+"». Règles : réponds uniquement en "+LN()+", en une ou deux phrases courtes et naturelles, avec un vocabulaire de niveau A2-B1. Reste dans ton personnage. Termine le plus souvent par une question ou une relance pour faire parler l'élève. Ne corrige pas ses erreurs, ne traduis rien, n'utilise ni markdown ni indication de mise en scène. Si l'élève écrit en français, réponds quand même en "+LN()+", simplement.";
  const script=()=>"Personnage : "+sc.open+"\n"+turns.map(t=>(t.role==="user"?"Élève : ":"Personnage : ")+t.content).join("\n");
  qbar(null,null,"Conversation","← Les scénarios",convList);body.append(el("div","kind","Jeu de rôle"));const h=el("h2");h.textContent=sc.title;body.append(h);
  const mission=el("div","tip");mission.append(el("b",null,"Ta mission. "));mission.append(document.createTextNode(sc.goal));body.append(mission);
  const log=el("div","chat");log.setAttribute("aria-live","polite");body.append(log);
  const bubble=(who,text)=>{const b=el("div","bub "+who),t=el("span");t.textContent=text;b.append(t);log.append(b);return b};
  const listen=(b,text)=>{if(canSpeak)b.append(sayBtn(text))};listen(bubble("ai",sc.open),sc.open);
  const note=el("p","fr");note.hidden=true;note.setAttribute("role","status");
  const box=typeBox("Ta réponse en "+LN(),"Envoyer",async val=>{box.lock(true);note.hidden=true;hintBox.hidden=true;turns.push({role:"user",content:val});bubble("me",val);box.inp.value="";
    const b=bubble("ai","…"),t=b.firstChild;b.scrollIntoView({block:"nearest",behavior:"smooth"});
    try{const r=await AI([{role:"user",content:RULES}].concat(turns),{cache:false,modelTier:"quick",onText:({text})=>{t.textContent=text}});
      t.textContent=r.text;turns.push({role:"assistant",content:r.text});listen(b,r.text);n++;bump();save();end.disabled=n<2;end.textContent=n<2?"Bilan après 2 répliques":"Terminer et voir le bilan"}
    catch(e){turns.pop();b.remove();log.lastChild.remove();box.inp.value=val;note.textContent=aiFail(e);note.hidden=false}
    box.lock(false);if(log.isConnected)box.inp.focus({preventScroll:true})});
  body.append(box.w,note);
  const hintBox=el("div","hint");hintBox.hidden=true;const row=el("div","rowb"),hint=btn("Que dire ?"),end=btn("Bilan après 2 répliques");end.disabled=true;
  hint.onclick=async()=>{hint.disabled=true;hintBox.hidden=false;hintBox.textContent="L'assistant cherche une idée…";
    try{await AI("Jeu de rôle en "+LN()+" pour un élève francophone (A2 vers B1).\nMission de l'élève : "+sc.goal+"\n\n"+script()+"\n\nPropose 2 réponses possibles que l'élève pourrait donner maintenant, en "+LN()+", chacune suivie de sa traduction française entre parenthèses. Une par ligne, sans numéro ni autre texte.",
        {cache:false,modelTier:"quick",onText:({text})=>{hintBox.textContent=text}})}catch(e){hintBox.textContent=aiFail(e)}hint.disabled=false};
  end.onclick=()=>bilan(k,sc,script(),n);row.append(hint,end);if(window.WEB)WEB.convExtra(row,k);body.append(row,hintBox)}
async function bilan(k,sc,script,n){qbar(null,null,"Bilan","← Les scénarios",convList);body.append(el("div","kind","Bilan de la conversation"));const h=el("h2");h.textContent=sc.title;body.append(h);
  const wait=el("p","fr","L'assistant relit tes répliques. Cela peut prendre jusqu'à une minute.");wait.setAttribute("role","status");body.append(wait);const host=body;
  S.cv=S.cv||{};S.cv[M[k].id]={t:day(),n};save();
  let r;try{r=await askJSON("Tu es professeur de langue ("+LN()+"). Voici un jeu de rôle écrit entre un personnage et un élève francophone (niveau A2 vers B1).\nMission de l'élève : "+sc.goal+"\nPoint de langue visé : "+sc.focus+"\n\n"+script+"\n\nAnalyse uniquement les répliques de l'élève. Réponds uniquement avec un objet JSON de cette forme : {\"resume\": \"deux phrases en français, honnêtes et encourageantes, sur ce qui est réussi et ce qui reste à travailler, en disant si le point de langue visé a été utilisé\", \"erreurs\": [{\"type\": \"grammaire\" ou \"vocabulaire\" ou \"orthographe\" ou \"registre\", \"dit\": \"ce que l'élève a écrit\", \"mieux\": \"la version corrigée en "+LN()+"\", \"regle\": \"l'explication en une phrase, en français\"}], \"mots\": [{\"it\": \"mot ou expression en "+LN()+", forme du dictionnaire\", \"fr\": \"traduction française\"}]}. Au plus 6 erreurs, les plus utiles d'abord ; tableau vide s'il n'y en a pas. Entre 3 et 6 mots ou expressions de cette conversation que l'élève gagnerait à retenir.")}
  catch(e){if(host.isConnected){wait.textContent=aiFail(e);const again=btn("Réessayer","primary");again.onclick=()=>bilan(k,sc,script,n);host.append(again)}return}
  if(!host.isConnected)return;wait.remove();const str=x=>typeof x==="string"?x:"";
  const sum=el("p");sum.textContent=str(r&&r.resume)||"Conversation terminée.";host.append(sum);
  const errs=(Array.isArray(r&&r.erreurs)?r.erreurs:[]).filter(e=>e&&str(e.mieux)).slice(0,6);
  errs.forEach(e=>logErr("conv:"+M[k].id,(str(e.type)||"erreur")+" → "+str(e.mieux),str(e.dit)));if(errs.length)save();
  host.append(el("h3",null,errs.length?"À corriger":"Aucune erreur relevée"));
  ["grammaire","vocabulaire","orthographe","registre"].concat([""]).forEach(type=>{const list=errs.filter(e=>type?e.type===type:!["grammaire","vocabulaire","orthographe","registre"].includes(e.type));if(!list.length)return;
    const sec=el("section","grp");sec.append(el("div","count",type||"autre"));
    list.forEach(e=>{const c=el("div","corr"),a=el("p","said"),b=el("p","better"),d=el("p","fr");a.textContent=str(e.dit);b.textContent=str(e.mieux);d.textContent=str(e.regle);c.append(a,b,d);if(canSpeak)c.append(sayBtn(str(e.mieux)));sec.append(c)});host.append(sec)});
  const mots=(Array.isArray(r&&r.mots)?r.mots:[]).filter(m=>m&&str(m.it)&&str(m.fr)).slice(0,6);
  if(mots.length){host.append(el("h3",null,"À retenir"));const ul=el("ul","nb");mots.forEach(m=>{const li=el("li"),it=el("span","it"),tr=el("span","tr"),acts=el("span","acts");it.textContent=m.it;tr.textContent=m.fr;acts.append(addBtn(m.it,m.fr));li.append(it,acts,tr);ul.append(li)});host.append(ul)}
  const row=el("div","rowb"),a=btn("Rejouer ce scénario","primary"),b=btn("Autre scénario"),c=btn("Retour à l'accueil");a.onclick=()=>conv(k);b.onclick=convList;c.onclick=home;row.append(a,b,c);host.append(row)}


/* ---------- Préparation d'une leçon : trois rédactions courtes, une relecture indépendante, puis enregistrement dans la base ----------
   La leçon est écrite en trois morceaux (explications, exercices, dialogue) pour que chaque réponse reste courte : une seule
   réponse trop longue était coupée et la création échouait. Le JSON est extrait du texte par la page elle-même. */
let DB=null,pendingBase=null;
const slug=t=>bare(t).replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,28)||"lecon";
function parseJSON(t){t=String(t||"");const f=t.match(/```(?:json)?\s*([\s\S]*?)```/);if(f)t=f[1];const a=t.indexOf("{"),z=t.lastIndexOf("}");
  if(a<0||z<a)throw new Error("no json");return JSON.parse(t.slice(a,z+1))}
async function askJSON(prompt,opts){const r=await AI(prompt,Object.assign({cache:false},opts||{}));
  try{return parseJSON(r.text)}catch(e){throw {code:r.truncated?"truncated":"invalid_json",message:"réponse illisible"}}}
function tidy(c){c=c&&typeof c==="object"?c:{};const A=x=>Array.isArray(x)?x:[];
  return{lessons:A(c.lessons).filter(isS).slice(0,3),vocab:A(c.vocab).filter(v=>Array.isArray(v)&&isS(v[0])&&isS(v[1])).map(v=>[v[0],v[1]]).slice(0,24),
    ex:A(c.ex).filter(x=>okEx(x)&&(x[0]!=="m"||x[2].length>=3)).slice(0,28),dlg:A(c.dlg).filter(l=>Array.isArray(l)&&l.length>=3&&l.slice(0,3).every(isS)).map(l=>l.slice(0,3)).slice(0,10),
    dq:A(c.dq).filter(x=>Array.isArray(x)&&x[0]==="m"&&okEx(x)&&x[2].length>=3).slice(0,3),
    scenario:c.scenario&&["title","role","goal","focus","open"].every(k=>isS(c.scenario[k]))?c.scenario:null}}
const enough=c=>c.lessons.length>=1&&c.vocab.length>=8&&c.ex.length>=10&&c.dlg.length>=4;
const seenList=x=>{const ss=slots(),pos=x?ss.findIndex(y=>y.n===x.n):ss.length;return ss.slice(0,Math.max(pos,0)).map(y=>"- "+y.l.t+" : "+(y.l.g||"")).join("\n")};
function ctx(job){const c=C(),x=job.slot;
  let s="Cours de "+c.name+" pour un francophone adulte qui veut parler en voyage, avec des amis, au travail et pour la culture. Il y consacre 20 à 30 minutes par jour. Toutes les explications et consignes sont en français.\n";
  if(x){s+="\nNiveau : "+x.lv.t+" ("+x.lv.cecr+").\nUnité "+x.un+" : "+x.u.t+". "+(x.u.goal||"")+"\nLeçon : "+x.l.t+"\nPoint de langue : "+(x.l.g||"")+"\nConsignes de l'auteur du programme : "+(x.l.b||"aucune")+"\n";
    s+="\nDéjà vu dans les leçons précédentes :\n"+(seenList(x)||"rien : c'est la toute première leçon.")+"\n\nRègle d'or : n'emploie que des structures déjà vues ou celle du jour, et avance lentement, avec beaucoup de réemploi.\n"}
  else{const cu=current();s+="\nDemande de l'apprenant : «"+job.text+"»\n";
    if(cu)s+="Il en est à : "+cu.lv.t+" ("+cu.lv.cecr+"), unité « "+cu.u.t+" ». En dehors du point demandé, n'emploie que des structures qu'il connaît déjà :\n"+(seenList(cu)||"les toutes premières bases.")+"\n"}
  const errs=(S.err||[]).slice(-8).map(e=>"- "+e.q+" → il a répondu : "+e.a).join("\n");if(errs)s+="\nSes erreurs récentes, à réemployer si le sujet s'y prête :\n"+errs+"\n";
  return s+"\nLa langue cible doit être irréprochable : au moindre doute sur une forme, choisis une autre phrase. Pas de paroles de chansons ni de marques.\n"}
const P_CORE=job=>ctx(job)+`
Écris maintenant la PREMIÈRE PARTIE de la leçon : les explications et le vocabulaire. Réponds uniquement avec un objet JSON :
{"title": "titre court de la leçon, en français", "topic": "le point travaillé, dix mots au plus", "lessons": ["<h2>…</h2>…", "<h2>…</h2>…"], "vocab": [["mot en langue cible", "traduction française"]]}
- lessons : 2 écrans en HTML, chacun commence par <h2>. Balises permises : h2 h3 p em b div span table tr th td. Tout tableau est dans <div class="scroll">. Un exemple : <div class="ex">phrase<span>traduction</span></div>. Une astuce : <p class="tip">…</p>. <em> met en valeur la forme étudiée. Explique par contraste avec le français : où c'est pareil, où un francophone se trompe.
- vocab : 14 paires utiles, les noms avec leur article.`;
const brief=core=>"\nExplications déjà écrites (résumé) : "+core.lessons.join(" ").replace(/<[^>]+>/g," ").replace(/\s+/g," ").slice(0,2200)+"\nVocabulaire de la leçon : "+core.vocab.map(v=>v[0]+" = "+v[1]).join(" ; ")+"\n";
const P_EX=(job,core)=>ctx(job)+brief(core)+`
Écris maintenant les EXERCICES de cette leçon, du plus facile au plus difficile. Réponds uniquement avec un objet JSON : {"ex": [ … ]}
18 exercices, en mélangeant quatre types :
- ["m", question, [bonne réponse, distracteur, distracteur, distracteur], explication] : la bonne réponse est TOUJOURS la première. La question est une phrase en langue cible avec un trou ___, ou une question en français. Aucun distracteur ne doit pouvoir être accepté.
- ["f", phrase en langue cible avec un seul ___, "réponse|variante acceptée", explication] : réponse de un à trois mots. Un infinitif à conjuguer se met entre parenthèses dans la phrase : Io ___ (andare) a Roma.
- ["o", phrase en français, sa traduction en langue cible de 3 à 10 mots]
- ["p", [[mot en langue cible, traduction], … 5 paires]]
Au moins 5 "m", 6 "f", 3 "o" et 1 "p". Chaque explication donne la règle en une phrase, en français. Réemploie le vocabulaire de la leçon et celui des leçons précédentes.`;
const P_DLG=(job,core)=>ctx(job)+brief(core)+`
Écris maintenant le DIALOGUE et la mise en situation de cette leçon. Réponds uniquement avec un objet JSON :
{"dlg": [["personnage", "réplique en langue cible", "traduction française"]], "dq": [["m", "question en français", ["bonne réponse", "faux", "faux", "faux"], "explication"]], "scenario": {"title": "titre en français", "role": "le personnage que jouera l'assistant, décrit en langue cible", "goal": "la mission de l'apprenant, en français", "focus": "le point de langue attendu, en français", "open": "la première réplique du personnage, en langue cible"}}
- dlg : 6 à 8 répliques naturelles, dans une situation de la vie réelle, qui emploient le point de la leçon.
- dq : exactement 3 questions de compréhension du dialogue ; la bonne réponse est toujours la première ; une des trois porte sur la langue (« pourquoi telle forme ? »).`;
function reviewPrompt(c){return "Tu es relecteur expert de "+LN()+". Voici une leçon destinée à des francophones, en JSON. Dans ex et dq : pour [\"m\", question, options, explication], la PREMIÈRE option doit être la seule bonne réponse ; pour [\"f\", phrase, réponse, explication], la réponse (variantes séparées par |) doit couvrir toutes les réponses correctes ; [\"o\", phrase française, phrase en langue cible] ; [\"p\", paires].\n\n"+JSON.stringify(c)+
  "\n\nRésous chaque exercice toi-même, puis signale uniquement les vrais problèmes : première option fausse, distracteur qui serait accepté, autre réponse correcte non prévue, faute de langue ou de traduction, affirmation fausse. Réponds uniquement avec un objet JSON de cette forme : {\"ex\": [{\"i\": 0, \"pb\": \"le problème en une phrase\", \"fix\": null}], \"dq\": [], \"vocab\": [{\"i\": 0, \"fix\": [\"mot\", \"traduction\"]}], \"dlg\": [{\"i\": 0, \"fix\": [\"personnage\", \"phrase\", \"traduction\"]}], \"lessons\": [{\"i\": 0, \"fix\": \"l'écran HTML corrigé en entier\"}]}. \"i\" est l'index à partir de 0. Dans ex et dq, \"fix\" est l'exercice corrigé au même format, ou null s'il vaut mieux le supprimer. Tableaux vides si tout est juste. Ne signale rien de purement stylistique."}
function applyReview(c,r){let fixed=0,cut=0;r=r&&typeof r==="object"?r:{};const A=x=>Array.isArray(x)?x:[],at=(arr,x)=>x&&Number.isInteger(x.i)&&x.i>=0&&x.i<arr.length;
  ["ex","dq"].forEach(k=>{const drop=new Set();A(r[k]).forEach(x=>{if(!at(c[k],x))return;const f=x.fix;
      if(Array.isArray(f)&&okEx(f)&&(f[0]!=="m"||f[2].length>=3)&&(k!=="dq"||f[0]==="m")){c[k][x.i]=f;fixed++}else{drop.add(x.i);cut++}});
    c[k]=c[k].filter((x,i)=>!drop.has(i))});
  A(r.vocab).forEach(x=>{if(at(c.vocab,x)&&Array.isArray(x.fix)&&isS(x.fix[0])&&isS(x.fix[1])){c.vocab[x.i]=[x.fix[0],x.fix[1]];fixed++}});
  A(r.dlg).forEach(x=>{if(at(c.dlg,x)&&Array.isArray(x.fix)&&x.fix.length>=3&&x.fix.slice(0,3).every(isS)){c.dlg[x.i]=x.fix.slice(0,3);fixed++}});
  A(r.lessons).forEach(x=>{if(at(c.lessons,x)&&isS(x.fix)){c.lessons[x.i]=x.fix;fixed++}});
  return{fixed,cut}}
const codeOf=e=>e&&e.code?" (code : "+e.code+")":"";
async function creer(job,st){cur=null;st=st||{};if(window.WEB&&WEB.keepAwake)WEB.keepAwake();const x=job.slot;
  qbar(null,null,x?"Préparation":"Leçon à la carte","← Accueil",home);body.append(el("div","kind",x?"Unité "+x.un+", leçon "+(x.k+1):"À la carte"));
  const h=el("h2");h.textContent=x?x.l.t:"Ta leçon se prépare";body.append(h);
  const quote=el("p","fr");quote.textContent=x?(x.l.g||""):"« "+job.text+" »";body.append(quote);
  const ul=el("ul","req"),mk=t=>{const li=el("li"),a=el("span"),b=el("span","count");a.textContent=t;b.textContent="à venir";li.append(a,b);ul.append(li);return b};
  const s1=mk("Explications et vocabulaire"),s2=mk("Exercices"),s3=mk("Dialogue et mise en situation"),s4=mk("Relecture indépendante"),s5=mk("Ajout à ton programme");body.append(ul);
  const note=el("p","fr","Compte deux à trois minutes. Tu peux revenir à l'accueil : la leçon s'ajoutera toute seule quand elle sera prête.");note.setAttribute("role","status");body.append(note);
  const host=body,here=()=>host.isConnected,row=el("div","rowb");
  const fail=(step,e,lead,btns)=>{if(!here())return;if(window.WEB&&WEB.resume&&WEB.resume(e,st,()=>creer(job,st),note,step))return;step.textContent="échec";note.textContent=(lead?lead+" ":"")+aiFail(e)+codeOf(e);
    btns.forEach(([t,fn,c])=>{const b=btn(t,c);b.onclick=fn;row.append(b)});host.append(row)};
  const again=[["Réessayer",()=>creer(job,st),"primary"],["Retour à l'accueil",home]];
  if(!AI)return fail(s1,{code:"not_granted"},"",[["Retour à l'accueil",home]]);
  if(!st.core){s1.textContent="en cours…";let r;try{r=await askJSON(P_CORE(job))}catch(e){return fail(s1,e,"",again)}
    const core=tidy({lessons:r&&r.lessons,vocab:r&&r.vocab});if(!core.lessons.length||core.vocab.length<8)return fail(s1,{code:"invalid_json"},"Les explications reçues étaient incomplètes.",again);
    st.core=core;st.title=isS(r.title)?r.title.slice(0,70):"Leçon à la carte";st.topic=isS(r.topic)?r.topic.slice(0,110):String(job.text||"").slice(0,110)}
  s1.textContent="fait";
  const doEx=async()=>{if(st.ex)return;s2.textContent="en cours…";const r=await askJSON(P_EX(job,st.core));const ex=tidy({ex:r&&r.ex}).ex;if(ex.length<10)throw {code:"invalid_json"};st.ex=ex;if(here())s2.textContent="fait"};
  const doDlg=async()=>{if(st.dlg)return;s3.textContent="en cours…";const r=await askJSON(P_DLG(job,st.core));const t=tidy({dlg:r&&r.dlg,dq:r&&r.dq,scenario:r&&r.scenario});if(t.dlg.length<4)throw {code:"invalid_json"};st.dlg=t;if(here())s3.textContent="fait"};
  const res=await Promise.allSettled([doEx(),doDlg()]);
  if(st.ex)s2.textContent="fait";if(st.dlg)s3.textContent="fait";
  const bad=res.find(r=>r.status==="rejected");if(bad)return fail(st.ex?s3:s2,bad.reason,"",again);
  let c={lessons:st.core.lessons,vocab:st.core.vocab,ex:st.ex,dlg:st.dlg.dlg,dq:st.dlg.dq,scenario:st.dlg.scenario};
  if(!st.reviewed&&!st.skip){s4.textContent="en cours…";
    try{const rv=applyReview(c,await askJSON(reviewPrompt(c)));st.reviewed=true;st.rv=rv;c=tidy(c);st.ex=c.ex;st.dlg={dlg:c.dlg,dq:c.dq,scenario:c.scenario};st.core={lessons:c.lessons,vocab:c.vocab}}
    catch(e){return fail(s4,e,"La leçon est écrite mais pas encore relue.",[["Réessayer la relecture",()=>creer(job,st),"primary"],["L'ajouter sans relecture",()=>creer(job,Object.assign(st,{skip:true}))]])}
    if(!enough(c))return fail(s4,{code:"invalid_json"},"La relecture a écarté trop d'exercices.",[["Recommencer",()=>creer(job),"primary"],["Retour à l'accueil",home]])}
  s4.textContent=st.reviewed?"fait":"ignorée";
  s5.textContent="en cours…";const course=C().id;
  const id=x?x.l.id:(st.id=st.id||(course+"-"+slug(st.topic)+"-"+Date.now().toString(36)));
  const order=x?(x.n+1)*10:Math.max(1000,...M.filter(m=>m.course===course&&m.custom).map(m=>m.order||0))+10;
  const doc={course,title:x?x.l.t:st.title,topic:x?(x.l.g||st.topic):st.topic,order,level:x?x.lv.cecr:"",status:"published",by:st.reviewed?"app":"app-non-relue",created:new Date().toISOString().slice(0,10),json:JSON.stringify(c)};
  if(!toLesson(id,doc))return fail(s5,{code:"invalid_json"},"La leçon n'a pas passé le contrôle final.",again);
  let saved=false;if(DB){try{await DB.collection("lessons").doc(id).set(doc);saved=true}catch(e){}}
  let b={courses:[],lessons:[]};try{b=JSON.parse(localStorage.getItem(BKEY))||b}catch(e){}
  b.lessons=(b.lessons||[]).filter(y=>y.id!==id).concat([saved?{id,d:doc}:{id,d:doc,local:true}]);try{localStorage.setItem(BKEY,JSON.stringify(b))}catch(e){}
  if(!here()){pendingBase=b;if(view==="home")home();return}
  applyBase(b);const mi=M.findIndex(m=>m.id==="L."+id);s5.textContent="fait";
  const rv=st.rv,parts=[];if(rv)parts.push(rv.fixed+rv.cut===0?"La relecture n'a rien trouvé à corriger.":"Relecture : "+rv.fixed+(rv.fixed>1?" points corrigés":" point corrigé")+", "+rv.cut+(rv.cut>1?" exercices retirés":" exercice retiré")+".");
  else parts.push("Leçon ajoutée sans relecture : signale toute réponse qui te semble fausse.");
  if(!saved)parts.push("Elle n'a pas pu être enregistrée dans la base pour l'instant : elle reste sur cet appareil, et l'enregistrement sera retenté à la prochaine ouverture.");
  note.textContent=parts.join(" ");if(!x){h.textContent=st.title;quote.textContent=st.topic}
  const go1=btn("Commencer la leçon","primary"),hb=btn("Retour à l'accueil");go1.onclick=()=>go(mi);hb.onclick=home;row.append(go1,hb);host.append(row)}

/* ---------- Mode audio : écouter, répondre à voix haute, répéter, sans regarder l'écran ----------
   La page ne peut pas écouter (pas de micro) : elle pose la question, laisse un silence pour répondre, puis donne la réponse
   et laisse un second silence pour la répéter. Chaque étape est une suite de morceaux : texte à dire (langue) ou silence. */
let AUD=null;
const decode=s=>{const t=document.createElement("textarea");t.innerHTML=String(s).replace(/<[^>]+>/g," ");return t.value.replace(/\s+/g," ").trim()};
function audioSteps(src){const T=C().speech||"it-IT",sl=t=>String(t).replace(/ \/ /g,", "),it=t=>({l:T,t:sl(t)}),fr=t=>({l:"fr-FR",t:sl(t)}),gap=s=>({p:s}),out=[];
  const n=t=>String(t).split(/\s+/).length,think=t=>3+.35*n(t),rep=t=>1.6+.45*n(t);
  if(src.kind==="lesson"){const m=M[src.mi];
    out.push([fr("Leçon : "+m.st+". Pendant les silences, réponds à voix haute, puis répète après moi.")]);
    out.push([fr("D'abord, le vocabulaire.")]);
    m.vocab.forEach(v=>out.push([it(v[0]),gap(1.2),fr(v[1]),gap(.5),it(v[0]),gap(rep(v[0]))]));
    out.push([fr("Maintenant, à toi de parler.")]);
    m.ex.forEach(x=>{
      if(x[0]==="o")out.push([fr("Comment dit-on : "+decode(x[1])),gap(think(x[2])),it(x[2]),gap(rep(x[2])),it(x[2]),gap(1)]);
      else if(x[0]==="f"){const q=decode(x[1]),a=x[2].split("|")[0],hint=(q.match(/\(([^)]*)\)/)||[])[1],full=filled(q,a),blank=q.replace(/\s*\([^)]*\)/g,"").replace(/___/g,"…");
        out.push([fr("Complète"+(hint?", avec : "+hint:"")+"."),it(blank),gap(think(full)),it(full),gap(rep(full))])}});
    out.push([fr("Pour finir, le dialogue. Écoute, puis répète chaque réplique.")]);
    m.dlg.forEach(l=>out.push([it(l[1]),gap(.4),fr(l[2]),gap(.4),it(l[1]),gap(rep(l[1]))]));
    out.push([fr("C'est fini pour cette leçon. Brava, bravo ! Tu pourras faire les exercices à l'écran une fois arrivé.")])}
  else{const V=vstat(),list=shuffle(V.due.length?V.due:V.nb).slice(0,30);
    out.push([fr(list.length+" mots de ton carnet. Je dis le mot en français : dis-le en "+LN()+" avant moi.")]);
    list.forEach(w=>out.push([fr(w.fr),gap(think(w.it)),it(w.it),gap(rep(w.it))]));
    out.push([fr("Révision terminée. Bravo !")])}
  return out}
function sayPart(part,token){return new Promise(res=>{
  if(part.p!=null){AUD.timer=setTimeout(res,part.p*1000*AUD.pace);return}
  let done=false;const fin=()=>{if(done)return;done=true;clearTimeout(AUD.guard);res()};
  try{const u=new SpeechSynthesisUtterance(part.t),isFr=part.l.startsWith("fr");u.lang=part.l;u.rate=isFr?1:AUD.rate;const v=pickVoice(part.l);if(v)u.voice=v;
    u.onend=fin;u.onerror=fin;UTT=u;AUD.guard=setTimeout(fin,2500+part.t.length*95/u.rate);try{speechSynthesis.resume()}catch(e){}speechSynthesis.speak(u)}catch(e){fin()}})}
async function audioPlay(){if(!AUD)return;const token=AUD.token=Date.now()+Math.random();AUD.playing=true;audioRender();
  while(AUD.i<AUD.steps.length){for(const part of AUD.steps[AUD.i]){if(!AUD||AUD.token!==token||view!=="audio")return;await sayPart(part,token)}
    if(!AUD||AUD.token!==token||view!=="audio")return;bump();AUD.i++;if(AUD.i%6===0)save();audioRender()}
  AUD.playing=false;save();audioRender()}
function audioStop(){if(!AUD)return;AUD.token=0;clearTimeout(AUD.timer);clearTimeout(AUD.guard);stopSpeech();AUD.playing=false}
async function wakeOn(){try{if(navigator.wakeLock&&!AUD.wl)AUD.wl=await navigator.wakeLock.request("screen");AUD.wl&&AUD.wl.addEventListener&&AUD.wl.addEventListener("release",()=>{if(AUD)AUD.wl=null})}catch(e){}}
function wakeOff(){try{AUD&&AUD.wl&&AUD.wl.release()}catch(e){}if(AUD)AUD.wl=null}
document.addEventListener("visibilitychange",()=>{if(!AUD||view!=="audio")return;if(document.hidden){if(AUD.playing){audioStop();AUD.cut=true}}else{audioRender()}});
function audioLeave(){audioStop();wakeOff();AUD=null;home()}
function audioSetup(){cur=null;if(AUD){audioStop();wakeOff();AUD=null}
  qbar(null,null,"Mode audio","← Accueil",audioLeave);view="audio";
  body.append(el("div","kind","Écouter et parler"));body.append(el("h2",null,"En voiture, mains libres"));
  body.append(el("p","fr","La page te parle : elle te donne une phrase en français ou un début de phrase, laisse un silence pour que tu répondes à voix haute en "+LN()+", puis te donne la bonne réponse et un silence pour la répéter. Rien à toucher pendant la séance."));
  if(!canSpeak){body.append(el("p","fr","Ce navigateur ne sait pas lire le texte à voix haute : le mode audio ne peut pas fonctionner ici."));return}
  const ss=slots(),cu=current(),ready=mine().filter(i=>M[i].vocab&&M[i].vocab.length),V=vstat();
  let pick=null;const opts=[];
  if(cu&&cu.mi>=0)opts.push({kind:"lesson",mi:cu.mi,label:"Leçon du jour : "+cu.l.t});
  else{const last=ss.filter(x=>x.mi>=0&&isDone(x)).pop();if(last)opts.push({kind:"lesson",mi:last.mi,label:"Dernière leçon faite : "+last.l.t})}
  if(V.nb.length)opts.push({kind:"words",label:(V.due.length?"Mes mots à réviser ("+V.due.length+")":"Mon carnet ("+Math.min(V.nb.length,30)+" mots)")});
  const g=el("div","grp");g.append(el("div","count","Quoi écouter"));const sg=el("div","opts");
  const choose=(o,b)=>{pick=o;[...sg.children].forEach(c=>c.setAttribute("aria-pressed",String(c===b)));go1.disabled=false};
  opts.forEach((o,k)=>{const b=el("button","opt");b.type="button";b.textContent=o.label;b.onclick=()=>choose(o,b);sg.append(b)});
  const sel=el("select");sel.id="aud-pick";sel.setAttribute("aria-label","Une autre leçon");sel.append(new Option("Une autre leçon prête…",""));
  ready.forEach(i=>sel.append(new Option(M[i].st,String(i))));sel.onchange=()=>{if(sel.value!=="")choose({kind:"lesson",mi:+sel.value,label:M[+sel.value].st},null)};
  g.append(sg,sel);body.append(g);
  const pg=el("div","grp");pg.append(el("div","count","Silences pour répondre"));const ps=el("div","seg");let pace=(S.au&&S.au.pace)||1;
  [[1,"Normaux"],[1.6,"Plus longs"]].forEach(([v,t])=>{const b=el("button","chip");b.type="button";b.textContent=t;b.setAttribute("aria-pressed",String(v===pace));b.onclick=()=>{pace=v;[...ps.children].forEach(c=>c.setAttribute("aria-pressed",String(c===b)))};ps.append(b)});
  pg.append(ps);body.append(pg);
  if(!pickVoice(C().speech||"it-IT"))body.append(el("p","fr","Attention : aucune voix en "+LN()+" n'est installée sur cet appareil. Ajoute-la dans les réglages de synthèse vocale avant de partir."));
  body.append(el("p","tip","Prépare tout avant de démarrer, téléphone sur son support. Garde l'écran allumé et la page ouverte : si l'écran s'éteint ou si tu changes d'application, la lecture s'arrête, et il faudra toucher « Reprendre » une fois à l'arrêt."));
  const go1=btn("Démarrer","primary");go1.disabled=true;go1.onclick=()=>{if(!pick)return;S.au={pace};save();
    AUD={src:pick,steps:audioSteps(pick),i:0,pace,rate:.85,token:0,playing:false,wl:null};wakeOn();audioPlay()};
  body.append(go1);if(opts.length)choose(opts[0],sg.firstChild)}
function audioRender(){if(!AUD||view!=="audio")return;const A=AUD,n=A.steps.length,end=A.i>=n;
  if(!A.ui||!A.ui.big.isConnected){qbar(0,"1 / "+n,"Mode audio","← Accueil",audioLeave);view="audio";
    const ui=A.ui={};ui.kind=el("div","kind");ui.big=el("div","aud-state");ui.big.setAttribute("role","status");ui.note=el("p","fr");
    ui.main=btn("Pause","primary aud-main");const row=el("div","rowb");ui.back=btn("Étape précédente");ui.skip=btn("Étape suivante");row.append(ui.back,ui.skip);ui.home=btn("Retour à l'accueil");
    ui.main.onclick=()=>{const end=A.i>=A.steps.length;if(end){A.i=0;A.cut=false;wakeOn();audioPlay()}else if(A.playing){audioStop();audioRender()}else{A.cut=false;wakeOn();audioPlay()}};
    ui.back.onclick=()=>{const was=A.playing;audioStop();A.i=Math.max(0,A.i-1);was?audioPlay():audioRender()};
    ui.skip.onclick=()=>{const was=A.playing;audioStop();A.i=Math.min(A.steps.length,A.i+1);was&&A.i<A.steps.length?audioPlay():audioRender()};
    ui.home.onclick=audioLeave;body.append(ui.kind,ui.big,ui.note,ui.main,row,ui.home)}
  const ui=A.ui,bar=document.querySelector(".bar .prog i"),cnt=document.querySelector(".bar .sub .count");
  if(bar)bar.style.width=Math.round(100*Math.min(A.i,n)/n)+"%";if(cnt)cnt.textContent=Math.min(A.i+1,n)+" / "+n;
  ui.kind.textContent=A.src.kind==="lesson"?M[A.src.mi].st:"Révision du carnet";
  ui.big.textContent=end?"Séance terminée":A.playing?"Écoute et réponds à voix haute":A.cut?"Lecture interrompue":"En pause";
  ui.note.textContent=A.cut&&!A.playing?"L'écran s'est éteint ou la page a été quittée. Une fois à l'arrêt, touche « Reprendre ».":"";ui.note.hidden=!ui.note.textContent;
  ui.main.textContent=end?"Recommencer":A.playing?"Pause":"Reprendre";ui.back.disabled=A.i===0;ui.skip.disabled=end;ui.home.hidden=!end}

/*CONJ-START*//* ---------- Conjugueur ----------
   Verbes irréguliers décrits un par un (IRR) ; tous les autres sont calculés par les règles des trois groupes.
   Champs : fr = traduction ; aux = "a" (avere), "e" (essere), "ea" (les deux selon l'emploi, avere par défaut), "ae" (les deux, essere par défaut) ;
   pres, cong (subjonctif présent), rem (passé simple) = 6 formes séparées par des espaces ; remS = radical fort du passé simple (io, lui, loro) ;
   imp = radical de l'imparfait (face → facevo) ; fut = radical du futur et du conditionnel ; pp = participe passé ; ger = gérondif ;
   impv = impératif tu (et impv5 = voi, quand il diffère du présent) ; isc = verbe en -ire avec -isc- ; base = verbe composé sur un autre (préfixe + formes). */
