function words(){const out=[],c=C().id;M.forEach((m,mi)=>{if(m.course===c)m.vocab.forEach((w,k)=>out.push({it:w[0],fr:w[1],mi,key:m.id+"-"+k}))});
  const cw=S.cw||{};Object.keys(cw).forEach(id=>{if(cw[id]&&(cw[id].c||"it")===c)out.push({it:cw[id].it,fr:cw[id].fr,mi:-1,key:"c-"+id})});return out}
/* Carnet : un mot y entre quand il est marqué « À revoir » ou raté au quiz, et n'en sort que si on le retire. */
const inNb=key=>{const nb=S.nb||{};return nb[key]===1||(nb[key]==null&&(S.v||{})[key]===2)};
function setV(key,val){S.v=S.v||{};S.nb=S.nb||{};S.sr=S.sr||{};if(val===2||(S.v[key]===2&&S.nb[key]==null))S.nb[key]=1;if(val===2)S.sr[key]={b:0,due:day()};S.v[key]=val}
function vstat(){const seen=[],all=words(),nb=[],due=[],v=S.v||{};
  all.forEach(o=>{const st=o.mi<0?{}:S[M[o.mi].id]||{},past=o.mi<0||st.done||(st.i||0)>M[o.mi].lessons.length;
    if(v[o.key]||past)seen.push(o);if(inNb(o.key)){nb.push(o);if(dueIn(o.key)<=0)due.push(o)}});
  return{seen,all,nb,due}}
function carnet(fromCourse){if(!fromCourse)cur=null;const V=vstat();
  qbar(null,null,"Mon carnet",fromCourse?"← Retour à la leçon":null,fromCourse?show:null);
  body.append(el("div","kind","Vocabulaire"));body.append(el("h2",null,"Mon carnet"));
  const info=el("p","fr");body.append(info);if(V.due.length){const rv=btn(V.due.length>1?"Réviser les "+V.due.length+" mots du jour":"Réviser le mot du jour","primary");rv.onclick=()=>{cur=null;quizRun({dir:(S.qz&&S.qz.dir)||"fr-it",src:"due",n:0})};body.append(rv)}
  const say=()=>{const n=vstat().nb.length;info.textContent=n?n+(n>1?" mots à garder sous la main.":" mot à garder sous la main.")+" Chaque mot revient en révision à intervalles croissants (1, 3, 7, 14 puis 30 jours) et reste ici tant que tu ne le retires pas.":"Ton carnet est vide. Les mots que tu marques « À revoir » sur les cartes, ou que tu rates au quiz, viendront s'y ranger. Tu peux aussi en ajouter à la main."};say();
  const groups={};V.nb.forEach(w=>(groups[w.mi]=groups[w.mi]||[]).push(w));
  Object.keys(groups).map(Number).sort((a,b)=>(a<0?99:a)-(b<0?99:b)).forEach(mi=>{const sec=el("section","grp");
    sec.append(el("div","count",mi<0?"Mes ajouts":M[mi].st));const ul=el("ul","nb");
    groups[mi].forEach(w=>{const li=el("li"),it=el("span","it"),tr=el("span","tr"),acts=el("span","acts");it.textContent=w.it;tr.textContent=w.fr;
      {const n=dueIn(w.key),tg=el("span","tag");tg.textContent=n<=0?"à réviser":n===1?"demain":"dans "+n+" j";it.append(tg)}
      if(canSpeak){const sb=sayBtn(w.it," ");sb.className="";sb.setAttribute("aria-label","Écouter "+w.it);sb.querySelector("span").remove();acts.append(sb)}
      const rm=el("button");rm.type="button";rm.textContent="Retirer";rm.setAttribute("aria-label","Retirer "+w.it+" du carnet");
      rm.onclick=()=>{S.nb=S.nb||{};S.v=S.v||{};S.nb[w.key]=0;if(S.sr)delete S.sr[w.key];if(S.v[w.key]===2)S.v[w.key]=1;if(w.mi<0){S.cw[w.key.slice(2)]=null}save();li.remove();if(!ul.children.length)sec.remove();say()};
      acts.append(rm);li.append(it,acts,tr);ul.append(li)});
    sec.append(ul);body.append(sec)});
  const form=el("form","addw panel");form.append(el("div","count","Ajouter un mot"));
  const pair=el("div","pair"),a=el("input"),b=el("input");a.id="cw-it";b.id="cw-fr";a.placeholder=cap(LN());b.placeholder="Français";
  [a,b].forEach(x=>{x.type="text";x.maxLength=80;x.autocomplete="off";x.setAttribute("autocapitalize","off");x.setAttribute("aria-label",x.placeholder)});
  pair.append(a,b);const add=btn("Ajouter au carnet","primary");add.type="submit";form.append(pair,add);
  form.addEventListener("submit",e=>{e.preventDefault();const it=a.value.trim(),fr=b.value.trim();if(!it||!fr){(it?b:a).focus();return}
    const id=Date.now().toString(36);S.cw=S.cw||{};S.cw[id]={it,fr,c:C().id};setV("c-"+id,2);save();carnet(fromCourse)});
  body.append(form);
  if(V.nb.length){const q=btn("Me tester sur mon carnet");q.onclick=()=>{cur=null;const cfg=Object.assign({dir:"fr-it",n:20},S.qz,{src:"nb"});S.qz=cfg;save();quizRun(cfg)};body.append(q)}}
function qbar(pct,count,title,backLabel,backFn){view="quiz";root.innerHTML="";stopSpeech();
  const bar=el("div","bar"),top=el("div","top"),back=el("button","linkbtn");back.type="button";back.textContent=backLabel||"← Accueil";back.onclick=backFn||home;
  const where=el("span","where");where.textContent=title||"Quiz de vocabulaire";top.append(back,where);bar.append(top);
  if(pct!=null){const p=el("div","prog");p.innerHTML='<i style="width:'+pct+'%"></i>';bar.append(p)}
  if(count){const sub=el("div","sub"),c=el("span","count");c.textContent=count;sub.append(c);bar.append(sub)}
  bar.append(syncEl());root.append(bar);body=el("main","body");root.append(body);window.scrollTo(0,0)}
function quizSetup(){cur=null;const V=vstat(),cfg=Object.assign({dir:"fr-it",src:"seen",n:20},S.qz);
  if(!V[cfg.src]||!V[cfg.src].length)cfg.src=V.seen.length?"seen":"all";
  qbar();body.append(el("div","kind","Réglages"));body.append(el("h2",null,"Quiz de vocabulaire"));
  const group=(label,key,opts)=>{const g=el("div","grp");g.append(el("div","count",label));const sg=el("div","seg");
    opts.forEach(([val,txt,off])=>{const b=el("button","chip");b.type="button";b.textContent=txt;b.disabled=!!off;b.setAttribute("aria-pressed",String(cfg[key]===val));
      b.onclick=()=>{cfg[key]=val;[...sg.children].forEach(x=>x.setAttribute("aria-pressed",String(x===b)))};sg.append(b)});g.append(sg);body.append(g)};
  group("Sens","dir",[["fr-it","Français → "+LN()],["it-fr",cap(LN())+" → français"]]);
  group("Mots","src",[["seen","Mots vus ("+V.seen.length+")",!V.seen.length],["nb","Mon carnet ("+V.nb.length+")",!V.nb.length],["all","Tout le cours ("+V.all.length+")"]]);
  group("Longueur","n",[[10,"10 questions"],[20,"20 questions"],[0,"Tous les mots"]]);
  if(!V.seen.length)body.append(el("p","fr","Tu n'as pas encore parcouru de cartes de vocabulaire : le quiz piochera dans tout le cours."));
  const go=btn("Lancer le quiz","primary");go.onclick=()=>{S.qz=cfg;save();quizRun(cfg)};body.append(go)}
function quizRun(cfg){const V=vstat(),toIt=cfg.dir==="fr-it";if(cfg.src==="due"&&!V.due.length)return home();let pool=shuffle(V[cfg.src]&&V[cfg.src].length?V[cfg.src]:V.all);if(cfg.n)pool=pool.slice(0,cfg.n);
  const A=w=>toIt?w.it:w.fr,Q=w=>toIt?w.fr:w.it;let i=0,ok=0;const miss=[];
  function ask(){if(i>=pool.length)return fin();const w=pool[i];
    qbar(Math.round(100*i/pool.length),(i+1)+" / "+pool.length);
    body.append(el("div","kind",(cfg.src==="due"?"Révision · ":"")+(toIt?"Français → "+LN():cap(LN())+" → français")));
    const q=el("p","word");q.textContent=Q(w);body.append(q);if(!toIt&&canSpeak)body.append(sayBtn(w.it));
    const others=V.all.filter(o=>A(o)!==A(w)&&Q(o)!==Q(w)),ds=[];
    const add=o=>{if(ds.length<3&&!ds.some(d=>A(d)===A(o)))ds.push(o)};
    shuffle(others.filter(o=>o.mi===w.mi)).slice(0,2).forEach(add);shuffle(others).forEach(add);
    const g=el("div","opts");
    shuffle([w].concat(ds)).forEach(o=>{const b=el("button","opt");b.type="button";b.textContent=A(o);if(o===w)b.dataset.k="0";
      b.onclick=()=>{[...g.children].forEach(c=>{c.disabled=true;if(c.dataset.k==="0")c.classList.add("ok")});const good=o===w;if(!good)b.classList.add("ko");
        if(good){ok++;if((S.v||{})[w.key]===2)setV(w.key,1)}else{setV(w.key,2);miss.push(w)}if(inNb(w.key))srs(w.key,good);bump();save();
        const f=el("div","fb "+(good?"ok":"ko"));f.setAttribute("role","status");
        f.append(el("strong",null,good?cheer():"Pas tout à fait."));
        const p=el("p");p.textContent=w.it+" = "+w.fr;f.append(p);if(canSpeak)f.append(sayBtn(w.it,"Écouter le mot"));
        const nx=btn("Continuer","primary");nx.onclick=()=>{i++;ask()};f.append(nx);body.append(f);nx.focus({preventScroll:true});f.scrollIntoView({block:"nearest",behavior:"smooth"})};
      g.append(b)});
    body.append(g)}
  function fin(){qbar(100);const pct=Math.round(100*ok/pool.length),e=el("div","end");e.append(el("div","kind","Quiz terminé"));
    e.append(el("div","score",pct+" %"));e.append(el("p",null,ok+" bonnes réponses sur "+pool.length+"."+(miss.length?" Les mots ratés sont rangés dans ton carnet.":" Aucun mot à revoir.")));
    if(miss.length){const ul=el("ul","miss");miss.forEach(w=>{const li=el("li"),b=el("b"),sp=el("span");b.textContent=w.it;sp.textContent=w.fr;li.append(b,sp);ul.append(li)});e.append(ul)}
    const r=el("div","rowb"),a=btn("Rejouer","primary"),c=btn("Changer les réglages"),h=btn("Retour à l'accueil");
    a.onclick=()=>quizRun(cfg);c.onclick=quizSetup;h.onclick=home;if(cfg.src==="due"){if(vstat().due.length){a.textContent="Continuer la révision";r.append(a)}r.append(h)}else r.append(a,c,h);e.append(r);body.append(e)}
  ask()}

